import{_ as t,o as r,c as e,a2 as s}from"./chunks/framework.B2QVIpOM.js";const b=JSON.parse('{"title":"港九潮州公会中学 · 2026年资料 · 中三 · 考试","description":"","frontmatter":{"schema":"exam-report-v3","generated_from":"assets/exam-feedback","school_slug":"school-83beb08a","school_zh":"港九潮州公会中学","school_en":"—","grade":"s3","year":"2026-source","year_label":"2026年资料","type":"written","title":"港九潮州公会中学 · 2026年资料 · 中三 · 考试","anonymous":true,"source_ids":["HKCC-S3-202605"],"rounds":["unknown"]},"headers":[],"relativePath":"reports/school-83beb08a/s3/2026-source-written.md","filePath":"reports/school-83beb08a/s3/2026-source-written.md"}'),p={name:"reports/school-83beb08a/s3/2026-source-written.md"};function n(a,o,c,l,g,h){return r(),e("div",null,[...o[0]||(o[0]=[s('<h1 id="港九潮州公会中学-·-2026年资料-·-中三-·-考试" tabindex="-1">港九潮州公会中学 · 2026年资料 · 中三 · 考试 <a class="header-anchor" href="#港九潮州公会中学-·-2026年资料-·-中三-·-考试" aria-label="Permalink to &quot;港九潮州公会中学 · 2026年资料 · 中三 · 考试&quot;">​</a></h1><p><a href="/hk-exam-web/schools/school-83beb08a">← 返回港九潮州公会中学资料库</a></p><blockquote><p>以下内容根据考试及面试资料整理，已作匿名化与书面化处理，非逐字实录。具体安排请以当次考试通知为准。</p></blockquote><h2 id="record-hkcc-s3-202605" tabindex="-1">资料来源：港九潮州公会中学插班中三及中四考情_2026年秋季.pdf <a class="header-anchor" href="#record-hkcc-s3-202605" aria-label="Permalink to &quot;资料来源：港九潮州公会中学插班中三及中四考情_2026年秋季.pdf {#record-hkcc-s3-202605}&quot;">​</a></h2><p><strong>资料类型：</strong> 机构整理考生复盘</p><p><strong>入学途径：</strong> 插班</p><p><strong>课程分支：</strong> 课程分支未注明</p><p><strong>反馈时间：</strong> 2026年5月</p><h3 id="轮次未注明-·-请以当次考试通知为准" tabindex="-1">轮次未注明 · 请以当次考试通知为准 <a class="header-anchor" href="#轮次未注明-·-请以当次考试通知为准" aria-label="Permalink to &quot;轮次未注明 · 请以当次考试通知为准&quot;">​</a></h3><blockquote><p><strong>考核安排：</strong> 各科分别注明</p><p><strong>分科时间</strong></p><p>资料合并介绍中三及中四，未区分各题所属年级，以下为共享参考。5月16日反馈：中文9:30—10:15，数学10:20—10:50，英语10:55开始，结束时间记为11:40或11:50。六月另一场题目不同，整理者认为形式相近。</p></blockquote><blockquote><p><strong>语文：</strong> 中文，口语未注明</p><p><strong>基础及排序</strong></p><p>四道选择题，涉及句意及古语理解。排序包含六句太空想象题材句子的重组，以及六个段落的概括与排序。</p><p><strong>现代文赏析</strong></p><p>第一人称叙事：男子遇到残疾女乞丐，因手头拮据只施舍五分硬币，后来发现对方假扮残疾行骗，感到悲哀。题目涉及悲哀的两层原因及文末“等待”的含义；考生觉得“等待”一题回答不够准确。</p><p><strong>文言文</strong></p><p>秦桧断案：为约束假冒文书者、防止其危害社会而授予其官职，文末有作者对秦桧的负面评价。考到“谒”的解释及秦桧昏庸的原因；考生回顾时发现“谒”释义有误。</p><p><strong>作文与个人思路</strong></p><p>作文涉及“学习的道义”。考生围绕扎实学习与浮躁学习作正反论证，引用冰心、黑塞、孔子、荀子等，讨论读书和温习的方法。所引人物及论点是该生的作答思路，并非必写条件。</p></blockquote><blockquote><p><strong>数学：</strong> 简体或繁体中文可选</p><p><strong>题型及知识点</strong></p><p>因式分解（平方差、十字相乘）、统计概率、一次函数（斜率、坐标、三角形面积）、不等式、二元一次方程生活应用、利息、三角函数，以及平截头体体积、水杯水位上升的计算。</p><p><strong>作答过程</strong></p><p>考生先做最后一道大题，耗时较多，导致另两道大题未完成；对上四分位数不熟悉，三角函数也有审题疏漏，最后没有检查时间。</p></blockquote><blockquote><p><strong>英语：</strong> 英语</p><p><strong>阅读理解</strong></p><p>题材为漫威与DC超级英雄世界观比较，含较多生词及俚语，如“cut from the same cloth”。整理者也提到英语阅读有排序题。</p><p><strong>看图写作</strong></p><p>以第一人称描述一家人吃面的照片，既写照片内容，也说明深层意义，并自拟标题。考生开始时误解题意，后来修正，但没有余时检查语法及拼写。</p></blockquote><blockquote><p><strong>学生与家长反馈：</strong></p><p><strong>两次考试比较</strong></p><p>考生认为相较此前宁波公学，中文更难、数学更容易但时限较紧；英语越往后越难，侧重词汇及灵活表达。该次整体较放松，但认为数学答题顺序及英语审题仍需改善。</p><p><strong>个人复盘方向</strong></p><p>计划加强中英文排序、文言字词及散文赏析，补足上四分位数与三角函数，练习数学用时和英文看图写作，并预留检查时间。</p></blockquote>',14)])])}const d=t(p,[["render",n]]);export{b as __pageData,d as default};
